-- Course catalog seed: modules, content, badges, challenges.
-- Safe to run against production. Idempotent via ON CONFLICT (id) DO NOTHING.

-- modules (4 rows)

-- content (37 rows)

-- badges (10 rows)

-- challenges (4 rows)

-- Keep the SERIAL sequences ahead of these fixed ids so future inserts don't collide.
SELECT setval('modules_id_seq', (SELECT MAX(id) FROM modules), true);
SELECT setval('content_id_seq', (SELECT MAX(id) FROM content), true);
SELECT setval('badges_id_seq', (SELECT MAX(id) FROM badges), true);
SELECT setval('challenges_id_seq', (SELECT MAX(id) FROM challenges), true);
